# -*- coding: utf-8 -*-
"""Small TensorFlow helpers shared by the layer implementations.

The helpers hide the differences between dense tensors, ``tf.SparseTensor``
and :mod:`scipy` sparse matrices so that the layers of :mod:`gnn` can be used
both inside a :class:`keras.Model` and standalone (eager mode).
"""

from __future__ import absolute_import, division, print_function

import numpy as np
import tensorflow as tf

__all__ = ['is_sparse', 'to_dense', 'dot', 'matmul', 'serialize_activation',
           'deserialize_activation', 'as_indices', 'static_dim']


def is_sparse(tensor):
    """Return ``True`` when ``tensor`` is a :class:`tf.SparseTensor`."""
    return isinstance(tensor, tf.SparseTensor)


def to_dense(tensor, default_value=0.0):
    """Densify ``tensor`` when it is sparse, otherwise return it unchanged."""
    if is_sparse(tensor):
        return tf.sparse.to_dense(tf.sparse.reorder(tensor),
                                  default_value=default_value)
    return tensor


def dot(x, y):
    """Matrix product supporting a sparse left hand side.

    Parameters
    ----------
    x : tf.Tensor or tf.SparseTensor
        Left operand of shape ``(n, k)``.
    y : tf.Tensor
        Dense right operand of shape ``(k, m)``.

    Returns
    -------
    tf.Tensor
        Dense result of shape ``(n, m)``.
    """
    if is_sparse(x):
        return tf.sparse.sparse_dense_matmul(x, y)
    return tf.matmul(x, y)


#: Alias of :func:`dot`.
matmul = dot


_ACTIVATIONS = {
    'relu': tf.nn.relu,
    'elu': tf.nn.elu,
    'softmax': tf.nn.softmax,
    'sigmoid': tf.nn.sigmoid,
    'tanh': tf.nn.tanh,
    'leaky_relu': tf.nn.leaky_relu,
    'linear': None,
    'identity': None,
    'none': None,
}


def serialize_activation(activation):
    """Serialize an activation to a JSON friendly value (its name)."""
    if activation is None:
        return None
    if isinstance(activation, str):
        return activation
    name = getattr(activation, '__name__', None)
    if name:
        return name
    try:  # pragma: no cover - keras objects
        return tf.keras.activations.serialize(activation)
    except Exception:  # pragma: no cover - last resort
        return str(activation)


def deserialize_activation(activation):
    """Turn the output of :func:`serialize_activation` back into a callable."""
    if activation is None or callable(activation):
        return activation
    if isinstance(activation, str):
        key = activation.lower()
        if key in _ACTIVATIONS:
            return _ACTIVATIONS[key]
        if hasattr(tf.nn, key):
            return getattr(tf.nn, key)
        try:
            return tf.keras.activations.get(activation)
        except Exception:  # pragma: no cover - unknown name
            raise ValueError("Unknown activation '{}'".format(activation))
    try:  # pragma: no cover - dict style keras config
        return tf.keras.activations.get(activation)
    except Exception:  # pragma: no cover
        raise ValueError("Unknown activation '{}'".format(activation))


def as_indices(tensor, dtype=tf.int32):
    """Cast ``tensor`` to an integer index tensor.

    :func:`gnn.graphsage.sample_neighs` returns ``float32`` arrays (as
    documented), while ``tf.gather``/``tf.nn.embedding_lookup`` require
    integer indices -- this helper performs the conversion for both numpy
    arrays and tensors.
    """
    if isinstance(tensor, (np.ndarray, list, tuple)):
        tensor = tf.convert_to_tensor(np.asarray(tensor))
    if tensor.dtype != dtype:
        tensor = tf.cast(tensor, dtype)
    return tensor


def static_dim(shape, axis=-1):
    """Return the static size of ``shape[axis]`` as a python ``int``."""
    if hasattr(shape, 'as_list'):
        shape = shape.as_list()
    value = list(shape)[axis]
    if value is None:
        raise ValueError(
            'The dimension {} of the input shape {} must be known '
            'statically.'.format(axis, shape))
    return int(value)

